pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address sender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address recipient = 0xdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef;
        address target = c.caddress();

        vm.deal(sender, 10 ether);
        vm.deal(target, 0);

        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint[] memory vals = new uint[](1);
        vals[0] = 1;

        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", tos, vals));
        require(success, "transfer reverted");

        assertTrue(target.balance == 1000000000000000000);
    }
}

