// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the caller to the allowed address
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(caller);
        // Call transfer with _tos containing caddress (the contract itself) and v=[2]
        address[] memory _tos = new address[](1);
        _tos[0] = address(c); // caddress is the contract's own address, which is 0x1f844685f7Bf86eFcc0e74D8642c54A257111923 initially, but after deployment it's this address?
        // Actually, caddress is a state variable set to 0x1f844685f7Bf86eFcc0e74D8642c54A257111923, not the contract itself.
        // So we need to use that address as recipient. Since it's externally owned, we can fund it.
        // But to measure balance, we use address(c).balance? No, caddress is not address(c).
        // Let's instead use address(c) as recipient by setting _tos[0] = address(c) and note that caddress is a different address.
        // The reference will send 2e18 wei to address(c), the buggy sends 2 wei. address(c).balance will differ.
        _tos[0] = address(c);
        uint[] memory v = new uint[](1);
        v[0] = 2;
        c.transfer(_tos, v);
        // Assert that address(c).balance is 2e18 wei (reference) vs 2 wei (buggy)
        assertTrue(address(c).balance == 2e18 wei);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address target = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

        address[] memory _tos = new address[](1);
        _tos[0] = target;
        uint[] memory v = new uint[](1);
        v[0] = 1;

        uint256 balanceBefore = address(c).balance;

        vm.prank(authorized);
        c.transfer(_tos, v);

        uint256 balanceAfter = address(c).balance;
        uint256 delta = balanceAfter - balanceBefore;

        // Reference sends 1e18 wei to caddress (target), which is this contract itself.
        // The contract's balance increases by 1e18 because the low-level call sends ether to itself.
        assertTrue(delta == 1e18);
    }
}
